-- Sprint 16 additive migration. Provider-neutral billing ledger; no Stripe SDK, keys, checkout, collection, or webhook.
create table public.subscription_plans(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,description text not null,monthly_price numeric(12,2),currency char(3)not null default'USD',limits jsonb not null,features text[]not null default'{}',active boolean not null default true,sort_order integer not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());insert into public.subscription_plans(code,name,description,monthly_price,limits,features,sort_order)values('starter','Starter','For small teams launching their CRM',49,'{"users":3,"storage_gb":10,"properties":250,"leads":1000,"deals":100,"ai_requests":0,"automation":0,"support":1}','{"Email support"}',1),('professional','Professional','For growing sales teams',149,'{"users":10,"storage_gb":50,"properties":2000,"leads":10000,"deals":1000,"ai_requests":5000,"automation":1,"support":2}','{"Priority support","Automation"}',2),('business','Business','For multi-team real estate operations',399,'{"users":30,"storage_gb":250,"properties":10000,"leads":50000,"deals":5000,"ai_requests":25000,"automation":1,"support":3}','{"Priority onboarding","Automation"}',3),('enterprise','Enterprise','Custom governance, capacity, and support',null,'{"users":null,"storage_gb":null,"properties":null,"leads":null,"deals":null,"ai_requests":null,"automation":1,"support":4}','{"Dedicated support","Custom limits"}',4)on conflict(code)do nothing;
create table public.subscriptions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),plan_id uuid not null references public.subscription_plans(id),status text not null default'trialing' check(status in('trialing','active','past_due','cancelled','suspended')),trial_ends_at timestamptz,current_period_starts_at timestamptz not null default now(),current_period_ends_at timestamptz,cancel_at_period_end boolean not null default false,seat_quantity integer not null default 1 check(seat_quantity>0),provider text not null default'inactive',provider_customer_id text,provider_subscription_id text,created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1,unique(workspace_id));
create table public.organization_usage(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),metric text not null,quantity numeric(18,3)not null default 0,period_start date not null,period_end date not null,updated_at timestamptz not null default now(),unique(workspace_id,metric,period_start));
create table public.organization_limits(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),metric text not null,limit_value numeric(18,3),source text not null default'plan',updated_at timestamptz not null default now(),unique(workspace_id,metric));
create table public.invoices(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),subscription_id uuid references public.subscriptions(id),invoice_number text not null,status text not null default'draft' check(status in('draft','open','paid','void','failed')),currency char(3)not null,subtotal numeric(18,2)not null default 0,tax numeric(18,2)not null default 0,total numeric(18,2)generated always as(subtotal+tax)stored,issued_at timestamptz,due_at timestamptz,paid_at timestamptz,download_url text,provider_invoice_id text,metadata jsonb not null default'{}',created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1,unique(organization_id,invoice_number));
create table public.billing_contacts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),company_name text not null,billing_email text not null,tax_id text,address jsonb not null default'{}',created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,unique(workspace_id));
create index subscription_org_idx on public.subscriptions(organization_id,workspace_id)where deleted_at is null;create index usage_period_idx on public.organization_usage(organization_id,workspace_id,period_start,period_end);create index invoices_recent_idx on public.invoices(organization_id,workspace_id,created_at desc)where deleted_at is null;
alter table public.subscription_plans enable row level security;alter table public.subscriptions enable row level security;alter table public.organization_usage enable row level security;alter table public.organization_limits enable row level security;alter table public.invoices enable row level security;alter table public.billing_contacts enable row level security;
create policy "plans_authenticated_read" on public.subscription_plans for select to authenticated using(active);create policy "subscriptions_admin_read" on public.subscriptions for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)in('organization_owner','organization_admin'));create policy "usage_admin_read" on public.organization_usage for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)in('organization_owner','organization_admin'));create policy "limits_admin_read" on public.organization_limits for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)in('organization_owner','organization_admin'));create policy "invoices_admin_read" on public.invoices for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)in('organization_owner','organization_admin'));create policy "billing_contacts_admin_read" on public.billing_contacts for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)in('organization_owner','organization_admin'));
create or replace function public.can_manage_billing(p_workspace uuid)returns boolean language sql stable security definer set search_path=public as $$select public.current_workspace_role(p_workspace)in('organization_owner','organization_admin')$$;
create or replace function public.provision_workspace_billing(p_workspace uuid,p_organization uuid,p_actor uuid)returns void language plpgsql security definer set search_path=public as $$declare v_plan subscription_plans%rowtype;v_start date=date_trunc('month',now())::date;v_end date=(date_trunc('month', now()) + interval '1 month' - interval '1 day')::date;begin select*into v_plan from subscription_plans where code='starter';insert into subscriptions(organization_id,workspace_id,plan_id,trial_ends_at,current_period_ends_at,seat_quantity,created_by,updated_by)values(p_organization,p_workspace,v_plan.id,now()+interval'14 days',now()+interval'14 days',greatest(1,(select count(*)from workspace_members where workspace_id=p_workspace and status='active')),p_actor,p_actor)on conflict(workspace_id)do nothing;insert into organization_limits(organization_id,workspace_id,metric,limit_value)select p_organization,p_workspace,key,(value#>>'{}')::numeric from jsonb_each(v_plan.limits)where jsonb_typeof(value)='number'on conflict(workspace_id,metric)do nothing;insert into organization_usage(organization_id,workspace_id,metric,quantity,period_start,period_end)values(p_organization,p_workspace,'users',(select count(*)from workspace_members where workspace_id=p_workspace and status='active'),v_start,v_end),(p_organization,p_workspace,'properties',(select count(*)from properties where workspace_id=p_workspace and deleted_at is null),v_start,v_end),(p_organization,p_workspace,'leads',(select count(*)from leads where workspace_id=p_workspace and deleted_at is null),v_start,v_end),(p_organization,p_workspace,'deals',(select count(*)from deals where workspace_id=p_workspace and deleted_at is null),v_start,v_end),(p_organization,p_workspace,'storage_gb',0,v_start,v_end),(p_organization,p_workspace,'ai_requests',0,v_start,v_end),(p_organization,p_workspace,'messages',0,v_start,v_end),(p_organization,p_workspace,'calls',0,v_start,v_end),(p_organization,p_workspace,'exports',0,v_start,v_end)on conflict(workspace_id,metric,period_start)do nothing;end$$;
do $$declare w record;begin for w in select id,organization_id,created_by from workspaces loop perform provision_workspace_billing(w.id,w.organization_id,w.created_by);end loop;end$$;create or replace function public.provision_billing_on_workspace()returns trigger language plpgsql security definer set search_path=public as $$begin perform provision_workspace_billing(new.id,new.organization_id,new.created_by);return new;end$$;create trigger provision_billing_after_workspace after insert on public.workspaces for each row execute function public.provision_billing_on_workspace();
create or replace function public.change_subscription_plan(p_workspace_id uuid,p_plan_code text,p_seat_quantity integer,p_expected_version integer)returns void language plpgsql security definer set search_path=public as $$declare s subscriptions%rowtype;p subscription_plans%rowtype;begin select*into s from subscriptions where workspace_id=p_workspace_id and deleted_at is null for update;if not found or not can_manage_billing(p_workspace_id)then raise exception'insufficient billing permission';end if;if s.version<>p_expected_version then raise exception'subscription changed by another user';end if;select*into p from subscription_plans where code=p_plan_code and active;if not found then raise exception'invalid plan';end if;if p_seat_quantity<(select count(*)from workspace_members where workspace_id=p_workspace_id and status='active')then raise exception'seat quantity cannot be below active users';end if;update subscriptions set plan_id=p.id,seat_quantity=p_seat_quantity,updated_by=auth.uid(),updated_at=now(),version=version+1 where id=s.id;delete from organization_limits where workspace_id=p_workspace_id and source='plan';insert into organization_limits(organization_id,workspace_id,metric,limit_value)select s.organization_id,p_workspace_id,key,case when jsonb_typeof(value)='null'then null else(value#>>'{}')::numeric end from jsonb_each(p.limits);end$$;
create or replace function public.cancel_subscription(p_workspace_id uuid,p_expected_version integer)returns void language plpgsql security definer set search_path=public as $$declare s subscriptions%rowtype;begin select*into s from subscriptions where workspace_id=p_workspace_id and deleted_at is null for update;if not found or not can_manage_billing(p_workspace_id)then raise exception'insufficient billing permission';end if;if s.version<>p_expected_version then raise exception'subscription changed by another user';end if;update subscriptions set cancel_at_period_end=true,updated_by=auth.uid(),updated_at=now(),version=version+1 where id=s.id;end$$;
create or replace function public.update_billing_contact(p_workspace_id uuid,p_input jsonb)returns void language plpgsql security definer set search_path=public as $$declare v_org uuid;begin select organization_id into v_org from workspaces where id=p_workspace_id;if v_org is null or not can_manage_billing(p_workspace_id)then raise exception'insufficient billing permission';end if;insert into billing_contacts(organization_id,workspace_id,company_name,billing_email,tax_id,created_by,updated_by)values(v_org,p_workspace_id,p_input->>'companyName',lower(p_input->>'billingEmail'),nullif(p_input->>'taxId',''),auth.uid(),auth.uid())on conflict(workspace_id)do update set company_name=excluded.company_name,billing_email=excluded.billing_email,tax_id=excluded.tax_id,updated_by=auth.uid(),updated_at=now(),version=billing_contacts.version+1;end$$;
create or replace function public.generate_draft_invoice(p_workspace_id uuid)returns uuid language plpgsql security definer set search_path=public as $$declare s subscriptions%rowtype;p subscription_plans%rowtype;v_id uuid;begin select*into s from subscriptions where workspace_id=p_workspace_id and deleted_at is null;if not found or not can_manage_billing(p_workspace_id)then raise exception'insufficient billing permission';end if;select*into p from subscription_plans where id=s.plan_id;insert into invoices(organization_id,workspace_id,subscription_id,invoice_number,currency,subtotal,created_by,metadata)values(s.organization_id,p_workspace_id,s.id,'DRAFT-'||to_char(now(),'YYYYMMDDHH24MISSMS'),p.currency,coalesce(p.monthly_price,0),auth.uid(),'{"placeholder":true,"payment_collection":false}')returning id into v_id;return v_id;end$$;
revoke all on function public.provision_workspace_billing(uuid,uuid,uuid),public.change_subscription_plan(uuid,text,integer,integer),public.cancel_subscription(uuid,integer),public.update_billing_contact(uuid,jsonb),public.generate_draft_invoice(uuid)from public;grant execute on function public.change_subscription_plan(uuid,text,integer,integer),public.cancel_subscription(uuid,integer),public.update_billing_contact(uuid,jsonb),public.generate_draft_invoice(uuid)to authenticated;
